import { NextResponse } from "next/server";
import type { Locale } from "@/lib/i18n/dictionaries";
import {
  isSpeechConfigured,
  resolveAudioContentType,
  SpeechTranscribeError,
  transcribeAudio,
} from "@/lib/ai/azureSpeech.server";

/**
 * POST /api/navi/speech
 * multipart/form-data: audio (prefer WAV PCM 16 kHz mono), locale, optional contentType
 * → { text: string } | { error, code?, debug? }
 *
 * 422 is ALWAYS generated by this route (never Azure's HTTP status).
 * Typical cause: Azure returned 200 with RecognitionStatus NoMatch → we map to NO_SPEECH.
 */
export async function POST(request: Request) {
  try {
    if (!isSpeechConfigured()) {
      return NextResponse.json(
        { error: "Azure Speech is not configured" },
        { status: 503 }
      );
    }

    const form = await request.formData();
    const audio = form.get("audio");
    const locale = (String(form.get("locale") || "en") as Locale) || "en";
    const declaredFromField = String(form.get("contentType") || "").trim();

    if (!(audio instanceof Blob) || audio.size === 0) {
      return NextResponse.json(
        { error: "Missing audio", code: "Empty audio", debug: { bytes: 0 } },
        { status: 400 }
      );
    }

    const buffer = await audio.arrayBuffer();
    const declared = declaredFromField || audio.type || "audio/wav";
    const contentType = resolveAudioContentType(buffer, declared);

    console.info("[navi/speech] upload", {
      blobSize: audio.size,
      blobType: audio.type,
      declared,
      contentType,
      bufferBytes: buffer.byteLength,
      locale,
    });

    try {
      const text = await transcribeAudio(buffer, contentType, locale);
      return NextResponse.json({ text });
    } catch (err) {
      if (err instanceof SpeechTranscribeError) {
        const status =
          err.code === "NO_SPEECH" || err.code === "Empty audio" ? 422 : 503;
        console.warn("[navi/speech] transcribe failed", {
          code: err.code,
          message: err.message,
          debug: err.debug,
        });
        return NextResponse.json(
          {
            error: err.code === "NO_SPEECH" ? "NO_SPEECH" : err.message,
            code: err.code,
            message: err.message,
            debug: err.debug,
          },
          { status }
        );
      }
      const message = err instanceof Error ? err.message : "Speech failed";
      console.error("[navi/speech] unexpected", message);
      return NextResponse.json({ error: message }, { status: 503 });
    }
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Speech request failed" },
      { status: 500 }
    );
  }
}
